Script:
Credits = { 
    states: [script[TransactionStates]],
    creditTypes: [
            { id: 1, name: "[resource_displayname[CreditNote]]" }, 
            { id: 2, name: "[resource_displayname[Replacement]]" }, 
            { id: 3, name: "[resource_displayname[DebitNote]]" },
            { id: 4, name: "[resource_displayname[SelfBillingCredit]]" }
     ],
    init: async function (app, container) {
        api.addToMetaCache([
            {
                "Name": "B2B",
                "Types": [
                    [meta[B2B/Credit]],
                    [meta[B2B/Company]]
                ]
            }
        ]);
        var dataSource = await model.getDatasource({ endpoint: "B2B/Credit", odataAppend: "/FromSystem(SystemId='" + session.app.Config.B2B.TransactionSource + "')?$expand=Companies" });
        (await [script[CreditGrid]]({element: container, dataSource: dataSource})).init();
    }
};
